    """Fill the interiors of partial vertical/horizontal rectangle strokes."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 8]
    if not pts:
        return out
    fill = 2 if pts[0] and grid[pts[0][0]][pts[0][1]] != 2 else 3
    # Find pairs of marked rows and columns, then fill only those interior
    # cells whose row and column both have marked endpoints somewhere.
    marked_rows = [r for r in range(h) if any(grid[r][c] != 8 for c in range(w))]
    marked_cols = [c for c in range(w) if any(grid[r][c] != 8 for r in range(h))]
    for r0 in marked_rows:
        for r1 in marked_rows:
            if r1 <= r0:
                continue
            for c0 in marked_cols:
                for c1 in marked_cols:
                    if c1 <= c0:
                        continue
                    # A rectangle is indicated by existing pixels on its edges.
                    edge_support = (
                        any(grid[r0][c] != 8 for c in range(c0, c1 + 1)) and
                        any(grid[r1][c] != 8 for c in range(c0, c1 + 1)) and
