    """Restore vertical strokes, then supported horizontal strokes."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foreground = {value for value in counts if value != background}
    out = [row[:] for row in grid]
    if not foreground:
        return out

    occupied = lambda value: value in foreground or value == 2
    rows_with_marks = [r for r in range(h) if any(grid[r][c] in foreground for c in range(w))]
    cols_with_marks = [c for c in range(w) if any(grid[r][c] in foreground for r in range(h))]
    if not rows_with_marks or not cols_with_marks:
        return out
    top, bottom = min(rows_with_marks), max(rows_with_marks)

    # Join marks in each marked column across its vertical extent.
    for c in cols_with_marks:
        rs = [r for r in range(h) if grid[r][c] in foreground]
        if len(rs) >= 2:
            for r in range(min(rs), max(rs) + 1):
                if out[r][c] == background:
                    out[r][c] = 2

    # Join horizontal strokes on the outermost marked rows, and on interior
    # rows with at least three original marks (e.g. a branching junction).
    for r in range(h):
        original_count = sum(grid[r][c] in foreground for c in range(w))
        if r not in (top, bottom) and original_count < 3:
            continue
        cs = [c for c in range(w) if occupied(out[r][c])]
        if len(cs) >= 2:
            for c in range(min(cs), max(cs) + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    return out

