 "content": "def transform(grid):
    """Bridge short gaps in aligned mark runs; long spans require support."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    marks = {v for v in counts if v != bg}
    out = [row[:] for row in grid]
    if not marks:
        return out

    def apply_line(coords, orientation):
        positions = [i for i,(r,c) in enumerate(coords) if grid[r][c] in marks]
        if len(positions) < 2:
            return
        # A line with three+ input marks defines its whole span; otherwise,
        # only fill a one-cell interruption bounded by two marks.
        intervals = [(positions[0], positions[-1])] if len(positions) >= 3 else [
            (a,b) for a,b in zip(positions,positions[1:]) if b-a == 2
        ]
        # Three marked cells with a far-separated singleton can describe a
        # distinct stroke. Restrict long vertical spans to local successive gaps.
        if orientation == 'v' and len(positions) >= 3:
            intervals = [(a,b) for a,b in zip(positions,positions[1:]) if b-a == 2]
        for a,b in intervals:
            for i in range(a+1,b):
                r,c=coords[i]
                if grid[r][c] == bg:
                    out[r][c]=2

    for r in range(h):
        apply_line([(r,c) for c in range(w)], 'h')
    for c in range(w):
        apply_line([(r,c) for r in range(h)], 'v')
    return out

if __name__ == '__main__':
