    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = {v for v in counts if v != bg}
    out = [row[:] for row in grid]
    if not fg:
        return out

    # Vertical: close the long straight stroke when there are at least three
    # source marks, or bridge a single missing cell between a pair.
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] in fg]
        if len(rs) >= 3:
            for r in range(rs[0], rs[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
        else:
            for a, b in zip(rs, rs[1:]):
                if b - a == 2:
                    out[a + 1][c] = 2

    # Horizontal: complete lines with three or more source marks, or a
    # one-cell gap between two marks. A four-mark pattern of three adjacent
    # marks and a separated endpoint is also a stroke in the examples.
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] in fg]
        intervals = []
        if len(cs) >= 3:
            intervals.append((cs[0], cs[-1]))
        for a, b in zip(cs, cs[1:]):
            if b - a == 2:
                intervals.append((a, b))
        if len(cs) == 4 and cs[1] == cs[0] + 1 and cs[2] == cs[1] + 1 and cs[3] == cs[2] + 3:
            intervals.append((cs[0], cs[3]))
        for a, b in intervals:
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

