    for c in range(w):
        vertical_marks[c] = [r for r in range(h) if grid[r][c] in foreground]
    strong_columns = {c for c, rows in vertical_marks.items() if len(rows) >= 3}

    # Restore supported vertical strokes.
    for c, rows in vertical_marks.items():
        if len(rows) >= 3:
            for r in range(rows[0], rows[-1] + 1):
