    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg = {v for row in grid for v in row if v != bg}
    out = [row[:] for row in grid]

    # Vertical features: any column with repeated marks is a candidate stroke.
    vmarks = {c: [r for r in range(h) if grid[r][c] in fg] for c in range(w)}
    vstrong = {c for c, rs in vmarks.items() if len(rs) >= 3}
    for c, rs in vmarks.items():
        if len(rs) >= 3:
            for r in range(rs[0], rs[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
        elif len(rs) == 2 and rs[1] - rs[0] == 2:
            out[rs[0] + 1][c] = 2

