    """Complete internal gaps on repeated straight strokes with color 2."""
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    foreground = {value for value in counts if value != background}
    out = [row[:] for row in grid]

    # Only extend a line when its original marks include an adjacent pair,
    # the evidence for a stroke rather than unrelated isolated points.
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] in foreground]
        has_run = any(b == a + 1 for a, b in zip(marks, marks[1:]))
        if has_run:
            for a, b in zip(marks, marks[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2

    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] in foreground]
        has_run = any(b == a + 1 for a, b in zip(marks, marks[1:]))
        if has_run:
            for a, b in zip(marks, marks[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    return out

if __name__ == "__main__":
